// A spectrum file: its first line is the name, then wavelength and value pairs.
export function parseSpectrum(text) {
  const [name, ...rows] = text.split(/\r?\n/).filter((line) => line.trim());
  const pairs = rows.map((row) => row.trim().split(/\s+/).map(Number));
  return { name: name.trim(), wavelengths: pairs.map((p) => p[0]), values: pairs.map((p) => p[1]) };
}

